// BraveBrand Team: the home.bravebrand.com team sheet, rebuilt as a Buzz page.
// Prebuilt API v1 module (generated by tools/build.py; edit the template).
// Hiring creates the employee in the selected community with agents.port, using
// the card read live from the member's tier on home.bravebrand.com.
export const inject = ["react", "pages", "agents", "host"];

const HOME = "https://home.bravebrand.com";
const ASSETS = "/*ASSETS*/";
const CSS = /*CSS*/"";
const FONTS = /*FONTS*/[];
const ICON = "/*ICON*/";
const STORE = "bravebrand.team.key";
// Any form of the tier link, or the bare 24-character key from it.
const LINK = /(?:^|[^0-9a-f])([0-9a-f]{24})(?![0-9a-f])/i;
const CLASSROOM = "https://www.skool.com/bravebrand/classroom";
const classroomLink = (medium) => `${CLASSROOM}?utm_source=buzz&utm_medium=${medium}`;

// Copy and geometry from the team sheet (index.html, SEATS and ROOMS).
const SEATS = [
  { id:'architect', pack:'architect', role:'Digital Home Manager', slot:'l1',
    stepName:'Step One', accent:'#4a7fb5', scale:1.1,
    stats:{get:'A backend, site and CRM on accounts you own',
      run:'The build, the standups, every upgrade',
      so:'Own the whole thing. No landlord, no rent.'},
    desc:'Builds your Digital Home, then moves in and runs it. Wears sunglasses because the future of your business is bright. Your first hire, and the calmest.' },
  { id:'strategist', pack:'brand-intelligence', role:'Brand Strategist', slot:'r1',
    stepName:'Step Two', accent:'#3d9e8c',
    stats:{get:'A brand playbook in your customers’ own words',
      run:'Deep market research, angles, your offer core',
      so:'Stop guessing who you’re talking to.'},
    desc:'Stands on the tallest rock and watches your market so you never have to guess. Comes back with your people, their exact words, and the one problem your brand should own.' },
  { id:'copywriter', pack:'copy-coach', role:'Copy Writer', slot:'l2',
    stepName:'Step Three', accent:'#c96f2a',
    stats:{get:'Sales pages, emails and hooks in your voice',
      run:'The 12-step sales framework behind every line',
      so:'Sound like yourself on your best day.'},
    desc:'Writes words that sell and sound like you. Has read a thousand first drafts and survived every one. The matchstick is not a phase.' },
  { id:'funnel', pack:'funnel-builder', role:'Funnel Builder', slot:'r2',
    stepName:'Step Four', accent:'#b6722c',
    stats:{get:'A live funnel wired into your Digital Home',
      run:'Quiz pages, lead capture, proof of every lead',
      so:'Wake up to leads instead of hunting them.'},
    desc:'Builds the machine that turns strangers into leads. Hugs every dollar it catches and can prove exactly where it came from. Trust the mask, check the numbers.' },
  { id:'content', pack:'content-manager', role:'Content Manager', slot:'l3',
    stepName:'Step Five', accent:'#8461c9',
    stats:{get:'An article engine and a real social calendar',
      run:'The drumbeat: slate, write, schedule, publish',
      so:'Ship every week without thinking about it.'},
    desc:'Posts today, plans tomorrow, never misses a beat. Everywhere at once, the way content has to be. The ear flops because the calendar never sleeps.' },
  { id:'adsmanager', pack:'blaze', role:'Video Editor', slot:'r3',
    stepName:'Step Six', accent:'#a1386e',
    stats:{get:'Edited clips, captions and videos ready to share',
      run:'Included editing tools, your editor, and Meta ad setup',
      so:'Drop in a video. Get a finished edit back.'},
    desc:'Drop a video into Buzz, tell Blaze what you want, and he can get to work. His included tools help trim footage, turn longer recordings into clips, add captions and export finished videos. Prefer your own editor? He can help connect your existing workflow and guide you through setup. He also helps connect Meta and prepare ads for your review. Blaze checks the video tools are ready and helps with any setup first.' },
  { id:'salesrep', pack:null, role:'Sales Manager', slot:'c',
    stepName:'Step Seven', accent:'#6b7d3f',
    stats:{get:'Booked calls on a calendar that syncs itself',
      run:'Pipeline, reminders, follow-ups, no-shows',
      so:'Walk into meetings that booked themselves.'},
    desc:'Politely relentless. Makes the calls, warms the leads, books the meetings, and never takes the third no personally. Still on the phone right now.' },
];
const ROOMS = {
  strategist:'inset(0% 0% 70% 0%)',
  copywriter:'inset(30% 50% 47.5% 10%)',
  content:   'inset(30% 10% 47.5% 50%)',
  architect: 'inset(52.5% 50% 27% 10%)',
  salesrep:  'inset(52.5% 10% 27% 50%)',
  funnel:    'inset(73% 50% 3% 10%)',
  adsmanager:'inset(73% 10% 3% 50%)',
};
const INTRO = 'Seven employees run your Digital Home. Hire them in order, starting with your Digital Home Manager. Press Employ Me and say hello.';

const MARKUP = `
<div class="bb-root">
<div class="bb-scroll">
<header id="topbar">
  <p class="brandline"><img class="wordmark" src="${HOME}/art/ui/bb-logo.png" alt="BraveBrand"><span class="pagename">/ Digital Home</span></p>
  <form id="gate" hidden><input id="gatelink" placeholder="Paste your BraveBrand access link" aria-label="BraveBrand access link" autocomplete="off"><button type="submit">Unlock my team</button></form>
  <div id="info"><button id="infobtn" type="button" aria-label="About this page" aria-describedby="infotip">i</button>
    <p id="infotip" role="tooltip">${INTRO}</p></div>
</header>
<main class="sheet">
  <h1 class="labelfont">Let’s Build Your Digital Home</h1>
  <p id="intro">${INTRO}</p>
  <p id="pulse"></p>
  <div class="board"><div class="center">
    <div class="housewrap">
      <div id="house" aria-hidden="true"><img id="housebase" src="${HOME}/art/house-dim.png" alt=""></div>
      <p id="pulse2"></p>
    </div>
    <div class="rightcol">
      <div class="crew" id="crew"></div>
      <div id="progress" aria-label="Hiring progress"></div>
    </div>
  </div></div>
</main>
<footer id="foot">© 2026 BraveBrand — Digital Home. Your business, in one home you own.<span id="tier" hidden> · <span id="tiername"></span> membership · <button type="button" id="changelink">Change access link</button></span></footer>
</div>
<div id="spotlight" role="dialog" aria-modal="true" aria-labelledby="spot-name">
  <div class="scrim" data-close></div>
  <div class="panel"><div class="spot-surface">
    <button class="spot-close" data-close aria-label="Close">×</button>
    <div class="spot-identity">
      <p class="spot-team" id="spot-team" hidden><span aria-hidden="true">✓</span> On your team</p>
      <div class="spot-card" id="spot-card"><img id="spot-img" alt=""><img class="anim" id="spot-anim" alt=""></div>
      <p class="spot-eyebrow" id="spot-eyebrow">Your agent</p>
      <h2 class="spot-name labelfont" id="spot-name"></h2>
    </div>
    <div class="spot-content">
      <p class="spot-desc" id="spot-desc"></p>
      <dl class="spot-stats" id="spot-stats"></dl>
      <div class="spot-act" id="spot-act"></div>
    </div>
  </div></div>
</div>
<canvas id="confetti"></canvas>
</div>`;

let fontsLoaded = false;
function loadFonts() {
  if (fontsLoaded || typeof FontFace === "undefined") return;
  fontsLoaded = true;
  for (const [family, weight, base64] of FONTS) {
    const bytes = Uint8Array.from(atob(base64), (c) => c.charCodeAt(0));
    const face = new FontFace(family, bytes.buffer, { weight, display: "swap" });
    face.load().then((loaded) => document.fonts.add(loaded), () => {});
  }
}

// The team sheet's behaviour, scoped to one shadow root. Returns its cleanup.
function mountSheet(root, { agents, host }) {
  const $ = (sel) => root.querySelector(sel);
  const shell = $(".bb-root");
  const reduced = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const canHover = matchMedia("(hover: hover) and (pointer: fine)").matches;
  const isMobile = () => shell.clientWidth <= 1100;
  const disposers = [];
  const on = (target, type, fn, opts) => {
    target.addEventListener(type, fn, opts);
    disposers.push(() => target.removeEventListener(type, fn, opts));
  };
  let alive = true;
  let key = localStorage.getItem(STORE) || "";
  const manifests = {};
  const cards = {};
  let membership = null;
  let gateError = "";
  let loadError = "";
  let checking = false;

  // Hired = an agent with the employee's exact name in this community.
  const agentNames = () => new Set(agents.snapshot().agents.map((a) => a.name));
  const displayOf = (s) => (s.pack && manifests[s.pack] && manifests[s.pack].display) || "";
  const hired = (s) => !!(s.pack && displayOf(s) && agentNames().has(displayOf(s)));
  const agentName = (s) => (/^[A-Z][a-z]+(?= \()/.exec(displayOf(s)) || [displayOf(s) || s.role])[0];

  // ---------- height: the board fills the page area like 100vh did ----------
  const sizer = new ResizeObserver(() => {
    shell.style.setProperty("--bbvh", `${shell.clientHeight}px`);
    if (isMobile() !== lastMobile) { lastMobile = isMobile(); renderAll(); }
  });
  let lastMobile = isMobile();
  sizer.observe(shell);
  disposers.push(() => sizer.disconnect());
  shell.style.setProperty("--bbvh", `${shell.clientHeight}px`);

  // ---------- rooms ----------
  const house = $("#house");
  for (const s of SEATS) {
    const img = document.createElement("img");
    img.className = "room"; img.dataset.room = s.id; img.alt = "";
    img.src = `${HOME}/art/house-busy.png`;
    img.style.clipPath = ROOMS[s.id];
    img.addEventListener("error", () => img.remove());
    house.appendChild(img);
  }
  const roomEl = (id) => house.querySelector(`[data-room="${id}"]`);

  // ---------- seats ----------
  const crew = $("#crew");
  for (const s of SEATS) {
    const b = document.createElement("button");
    b.className = "seat"; b.type = "button";
    b.dataset.seat = s.id; b.dataset.slot = s.slot;
    b.setAttribute("aria-label", s.role);
    b.innerHTML = `
      <span class="fig" style="${s.scale ? `--figscale:${s.scale}` : ""}">
        <img src="${HOME}/art/crew/${s.id}.png" alt="">
        <img class="anim" alt="">
      </span>
      <span class="srole labelfont">${s.role}</span>
      <span class="sdesc">${s.desc}</span>
      <span class="badge"><span class="btext"></span><span class="freshdot"></span></span>`;
    crew.appendChild(b);
    s.el = b; s.fig = b.querySelector(".fig"); s.anim = b.querySelector(".anim");
  }

  // ---------- idle loops: animated stills with true alpha ----------
  // Buzz plays no website video, so each loop is an animated WebP. The still
  // is the loop's own first frame, so the swap is the same instant flip.
  const loopUrl = (id) => `${ASSETS}/loops/${id}.webp`;
  function arm(img, id) {
    if (img.dataset.armed) return img.dataset.dead !== "1";
    img.dataset.armed = "1";
    img.addEventListener("error", () => { img.dataset.dead = "1"; }, { once: true });
    img.src = loopUrl(id);
    return true;
  }
  function reveal(fig, img, still) {
    const show = () => {
      if (!still()) return;
      fig.classList.add("playing");
      requestAnimationFrame(() => requestAnimationFrame(() => still() && fig.classList.add("settled")));
    };
    if (img.complete && img.naturalWidth) show();
    else img.addEventListener("load", show, { once: true });
  }
  function seatPlay(s) {
    s.hovering = true;
    if (reduced || !arm(s.anim, s.id)) return;
    reveal(s.fig, s.anim, () => s.hovering && s.anim.dataset.dead !== "1");
  }
  function seatPause(s) {
    s.hovering = false;
    s.fig.classList.remove("playing", "settled");
  }
  if (canHover) {
    for (const s of SEATS) {
      on(s.el, "pointerenter", () => {
        seatPlay(s);
        const r = roomEl(s.id); if (r) r.classList.add("on");
      });
      on(s.el, "pointerleave", () => {
        seatPause(s);
        const r = roomEl(s.id); if (r && !hired(s)) r.classList.remove("on");
      });
    }
    // warm the loops once the page settles so the first hover plays at once
    if (!reduced) {
      const warm = setTimeout(() => { for (const s of SEATS) arm(s.anim, s.id); }, 600);
      disposers.push(() => clearTimeout(warm));
    }
  }

  // ---------- the hiring track ----------
  const progress = $("#progress");
  progress.innerHTML = `<div class="trackrow"><span id="trackcount"></span><span id="tracknext"></span></div>
    <div class="meter" role="progressbar" aria-valuemin="0" aria-valuemax="${SEATS.length}"><div class="meterfill"></div></div>`;
  function renderProgress() {
    const n = SEATS.filter(hired).length;
    const next = SEATS.find((s) => !hired(s));
    $("#trackcount").textContent = `${n} / ${SEATS.length} hired`;
    $("#tracknext").textContent = !membership ? "Your team is waiting" : next ? `Next: ${next.role}` : "Team complete";
    progress.querySelector(".meterfill").style.width = `${(n / SEATS.length) * 100}%`;
    const meter = progress.querySelector(".meter");
    meter.setAttribute("aria-valuenow", String(n));
    meter.setAttribute("aria-valuetext", `${n} of ${SEATS.length} hired`);
  }

  // ---------- pulse + gate ----------
  let pulseFlash = null;
  function renderPulse() {
    const el = $("#pulse"), el2 = $("#pulse2");
    $("#gate").hidden = !!membership;
    $("#tier").hidden = !membership;
    if (membership) $("#tiername").textContent = membership.tier === "premium" ? "Premium" : "Standard";
    if (pulseFlash) { el.textContent = el2.textContent = pulseFlash; return; }
    if (!membership) {
      el.textContent = gateError || loadError || "Paste your BraveBrand access link above to unlock your team.";
      el2.textContent = gateError || loadError;
      return;
    }
    el.textContent = el2.textContent = "";
  }
  function flashPulse(msg, ms) {
    pulseFlash = msg; renderPulse();
    const t = setTimeout(() => { pulseFlash = null; if (alive) renderPulse(); }, ms);
    disposers.push(() => clearTimeout(t));
  }
  function unlock(text) {
    const match = LINK.exec(text || "");
    if (!match) { gateError = "That isn't a BraveBrand access link. Copy the full link from your course and paste it here."; renderAll(); return; }
    localStorage.setItem(STORE, match[1].toLowerCase());
    key = match[1].toLowerCase(); gateError = "";
    boot();
  }
  on($("#gate"), "submit", (e) => { e.preventDefault(); unlock($("#gatelink").value); });
  on($("#changelink"), "click", () => {
    localStorage.removeItem(STORE); key = ""; membership = null; gateError = "";
    for (const k of Object.keys(manifests)) delete manifests[k];
    for (const k of Object.keys(cards)) delete cards[k];
    renderAll(); $("#gatelink").focus();
  });
  on($("#infobtn"), "click", () => $("#info").classList.toggle("open"));

  // ---------- badges + rooms ----------
  const HIRED_HTML = `<img src="${HOME}/art/ui/hired-check.svg" alt=""> Hired`;
  function renderSeat(s) {
    const badge = s.el.querySelector(".badge");
    const btext = badge.querySelector(".btext");
    const m = s.pack ? manifests[s.pack] : null;
    badge.classList.toggle("hired", hired(s));
    badge.classList.remove("act", "soon", "fresh");
    if (isMobile()) {
      if (!s.pack) { btext.textContent = "In training"; badge.classList.add("soon"); }
      else if (m && m.locked) { btext.textContent = "Unlock with Premium"; badge.classList.add("act"); }
      else if (m && !hired(s)) { btext.textContent = "Employ Me"; badge.classList.add("act"); }
      else if (hired(s)) { btext.innerHTML = HIRED_HTML; }
      else { btext.textContent = s.stepName; }
    } else if (hired(s)) {
      btext.innerHTML = HIRED_HTML;
    } else {
      btext.textContent = s.role;
    }
    const r = roomEl(s.id);
    if (r) r.classList.toggle("on", hired(s) || !!s.hovering);
    s.el.setAttribute("aria-label", `${s.role}${hired(s) ? ", on your team" : ""}`);
  }
  function renderAll() {
    if (!alive) return;
    SEATS.forEach(renderSeat);
    renderProgress();
    renderPulse();
    if (open) renderSpotAct(open);
  }

  // ---------- spotlight ----------
  const spot = $("#spotlight");
  const spotCard = $("#spot-card");
  const spotImg = $("#spot-img");
  let open = null, returnFocus = null, hiring = null, hireError = "";

  function renderSpotAct(s) {
    $("#spot-name").textContent = s.role;
    $("#spot-eyebrow").textContent = "Your agent";
    const act = $("#spot-act");
    const m = s.pack ? manifests[s.pack] : null;
    $("#spot-team").hidden = !m || m.locked || !hired(s);
    if (!s.pack) { act.innerHTML = '<span class="spot-soon">In training. Coming soon.</span>'; return; }
    if (!m) {
      if (membership) {
        act.innerHTML = loadError
          ? `<span class="spot-tiny">${loadError}</span><button class="cta" data-retry>Try again</button>`
          : `<span class="spot-tiny">Getting ${s.role} ready\u2026</span>`;
        return;
      }
      const typed = act.querySelector("#spotlink");
      const kept = typed ? typed.value : "", focused = typed && root.activeElement === typed;
      act.innerHTML = `<form class="spot-unlock" data-unlock>
          <label class="spot-tiny" for="spotlink">Paste the access link from your course to hire your team.</label>
          <input id="spotlink" placeholder="https://home.bravebrand.com/\u2026" autocomplete="off">
          <button class="cta" type="submit"${checking ? " disabled" : ""}>${checking ? "Checking\u2026" : "Unlock my team"}</button>
        </form>
        <span class="spot-tiny">${gateError || loadError || `No link yet? It's in your course in the <a href="${classroomLink("spotlight")}" target="_blank" rel="noopener">BraveBrand Classroom</a>.`}</span>`;
      const field = act.querySelector("#spotlink");
      field.value = kept;
      if (focused) field.focus();
      return;
    }
    if (m.locked) {
      act.innerHTML = `<a class="cta" href="${classroomLink("premium")}" target="_blank" rel="noopener">Unlock with Premium</a>`;
      return;
    }
    if (hired(s)) {
      act.innerHTML = `<span class="spot-tiny">${agentName(s)} is on your team in this community. Find them in Agents and say hello.</span>`;
      return;
    }
    const busy = hiring === s.id;
    act.innerHTML = `<button class="cta" data-hire="${s.id}"${busy ? " disabled" : ""}>${busy ? "Hiring…" : "Employ Me"}</button>
      <span class="spot-tiny">${hireError || `${agentName(s)} joins this community straight away. Say hello in Buzz.`}</span>`;
  }

  function openSpot(s) {
    if (!open) returnFocus = root.activeElement;
    if (open !== s) hireError = "";
    open = s;
    $("#spot-stats").innerHTML = s.stats
      ? `<div><dt>You get</dt><dd>${s.stats.get}</dd></div>
         <div><dt>They run</dt><dd>${s.stats.run}</dd></div>
         <div><dt>So you</dt><dd>${s.stats.so}</dd></div>` : "";
    $("#spot-desc").textContent = s.desc;
    renderSpotAct(s);
    spot.classList.add("open");
    $(".bb-scroll").inert = true;
    spotCard.classList.remove("playing", "settled");
    spotCard.style.setProperty("--figscale", s.scale || 1);
    spotImg.src = `${HOME}/art/crew/${s.id}.png`;
    const anim = $("#spot-anim");
    anim.removeAttribute("src"); delete anim.dataset.armed; delete anim.dataset.dead;
    if (!reduced && arm(anim, s.id)) reveal(spotCard, anim, () => open === s && anim.dataset.dead !== "1");
    spot.querySelector(".spot-close").focus();
  }
  function closeSpot() {
    open = null; hireError = "";
    spot.classList.remove("open");
    $(".bb-scroll").inert = false;
    if (returnFocus && returnFocus.isConnected) returnFocus.focus({ preventScroll: true });
  }
  for (const el of spot.querySelectorAll("[data-close]")) on(el, "click", closeSpot);
  on(spot.querySelector(".panel"), "click", (e) => { if (e.target === e.currentTarget) closeSpot(); });
  on(shell, "keydown", (e) => {
    if (!open) return;
    if (e.key === "Escape") { e.preventDefault(); closeSpot(); return; }
    if (e.key !== "Tab") return;
    const items = [...spot.querySelectorAll("button:not(:disabled),a[href]")].filter((el) => el.getClientRects().length);
    const index = items.indexOf(root.activeElement);
    if (e.shiftKey && index <= 0) { e.preventDefault(); items[items.length - 1]?.focus(); }
    else if (!e.shiftKey && (index === items.length - 1 || index < 0)) { e.preventDefault(); items[0]?.focus(); }
  });
  for (const s of SEATS) on(s.el, "click", () => {
    if (!isMobile() || !s.pack) return openSpot(s);
    const m = manifests[s.pack];
    if (!m) return openSpot(s);
    if (m.locked) { window.open(classroomLink("premium"), "_blank", "noopener"); return; }
    if (!hired(s)) return doHire(s, s.el.querySelector(".badge"));
    openSpot(s);
  });
  on(spot, "submit", (e) => {
    const form = e.target.closest("form[data-unlock]");
    if (!form) return;
    e.preventDefault();
    unlock(form.querySelector("input").value);
  });
  on(spot, "click", (e) => {
    if (e.target.closest("button[data-retry]")) { loadError = ""; boot(); return; }
    const button = e.target.closest("button[data-hire]");
    if (!button || button.disabled) return;
    const s = SEATS.find((q) => q.id === button.dataset.hire);
    if (s) doHire(s, null);
  });

  // ---------- confetti ----------
  const canvas = $("#confetti");
  const ctx2d = canvas.getContext("2d");
  let parts = [], raf = null;
  function burst(x, y, colors, n = 90) {
    if (reduced) return;
    canvas.width = shell.clientWidth; canvas.height = shell.clientHeight;
    for (let i = 0; i < n; i++) {
      const a = Math.random() * Math.PI * 2, v = 4 + Math.random() * 7;
      parts.push({ x, y, vx: Math.cos(a) * v, vy: Math.sin(a) * v - 3,
        w: 4 + Math.random() * 5, h: 6 + Math.random() * 6, rot: Math.random() * Math.PI,
        vr: (Math.random() - .5) * .3, c: colors[i % colors.length], life: 70 + Math.random() * 40 });
    }
    if (!raf) tick();
  }
  function tick() {
    ctx2d.clearRect(0, 0, canvas.width, canvas.height);
    parts = parts.filter((p) => p.life > 0 && p.y < canvas.height + 20);
    for (const p of parts) {
      p.x += p.vx; p.y += p.vy; p.vy += .22; p.vx *= .99; p.rot += p.vr; p.life--;
      ctx2d.save(); ctx2d.translate(p.x, p.y); ctx2d.rotate(p.rot);
      ctx2d.globalAlpha = Math.min(1, p.life / 30);
      ctx2d.fillStyle = p.c; ctx2d.fillRect(-p.w / 2, -p.h / 2, p.w, p.h); ctx2d.restore();
    }
    raf = parts.length && alive ? requestAnimationFrame(tick) : (ctx2d.clearRect(0, 0, canvas.width, canvas.height), null);
  }
  disposers.push(() => { if (raf) cancelAnimationFrame(raf); });

  // ---------- hire: the ceremony, then the employee joins ----------
  async function doHire(s, anchor) {
    const m = manifests[s.pack];
    if (!m || m.locked || hired(s) || hiring) return;
    const type = agents.types().filter((t) => !t.remote).find((t) => /claude/i.test(t.title)) ||
      agents.types().filter((t) => !t.remote)[0];
    if (!type) { hireError = "Switch on Claude under Settings → Agent setup first."; return renderAll(); }
    hiring = s.id; hireError = ""; renderAll();
    try {
      let card = cards[s.pack];
      if (!card) {
        try { card = await json(`${HOME}/${key}/${s.pack}/${m.card}`); }
        catch { throw new Error(OFFLINE); }
        if (card) cards[s.pack] = card;
      }
      const def = card && card.definition;
      if (!def || typeof def.systemPrompt !== "string" || !def.name) throw new Error("The employee card didn't load. Try again.");
      const firstEver = !SEATS.some(hired);
      await agents.port({ source: "shared", type: type.key, name: def.name,
        picture: `${HOME}/art/${AVATARS[s.pack]}`, instructions: def.systemPrompt });
      if (!alive) return;
      hiring = null;
      if (open) closeSpot();
      renderAll();
      const colors = [s.accent, "#16314c", s.accent, "#bbdcef"];
      const target = (isMobile() && anchor) ? anchor : (roomEl(s.id) || house);
      const box = target.getBoundingClientRect(), frame = shell.getBoundingClientRect();
      burst(box.left - frame.left + box.width / 2, box.top - frame.top + box.height / 2, colors, firstEver ? 140 : 90);
      if (firstEver) {
        const t = setTimeout(() => burst(shell.clientWidth / 2, shell.clientHeight / 3, colors, 90), 350);
        disposers.push(() => clearTimeout(t));
        flashPulse("Your company just made its first hire.", 6000);
      } else {
        flashPulse(`${agentName(s)} just joined your team.`, 4000);
      }
    } catch (error) {
      if (!alive) return;
      hiring = null; hireError = String((error && error.message) || error);
      renderAll();
    }
  }

  // ---------- data ----------
  // undefined = the file isn't there (or isn't JSON); throws = couldn't reach
  // BraveBrand. Network trouble retries and never forgets the member's link.
  async function json(url) {
    let last;
    for (let attempt = 0; attempt < 3; attempt++) {
      try {
        const response = await host.request({ url, method: "GET", timeoutMs: 20000 });
        if (response.status >= 500) throw new Error(`BraveBrand answered ${response.status}`);
        if (response.status < 200 || response.status >= 300) return undefined;
        try { return JSON.parse(response.body); } catch { return undefined; }
      } catch (error) {
        last = error;
        await new Promise((r) => setTimeout(r, 800 * (attempt + 1)));
      }
    }
    throw last;
  }
  const OFFLINE = "Couldn't reach BraveBrand. Check your internet connection, then try again.";
  async function boot() {
    renderAll();
    if (!/^[0-9a-f]{24}$/.test(key)) return;
    checking = true; loadError = ""; renderAll();
    let value;
    try { value = await json(`${HOME}/${key}/membership.json`); }
    catch { if (alive) { checking = false; loadError = OFFLINE; renderAll(); } return; }
    if (!alive) return;
    checking = false;
    if (!value || !["premium", "standard"].includes(value.tier)) {
      membership = null; gateError = "That access link isn't recognised. Copy it again from your course.";
      localStorage.removeItem(STORE); key = "";
      return renderAll();
    }
    membership = value;
    renderAll();
    await Promise.all(SEATS.filter((s) => s.pack).map(async (s) => {
      try {
        const manifest = await json(`${HOME}/${key}/${s.pack}/manifest.json`);
        if (manifest && alive) { manifests[s.pack] = manifest; renderAll(); }
      } catch { if (alive) { loadError = OFFLINE; renderAll(); } }
    }));
  }
  disposers.push(agents.subscribe(() => renderAll()));
  boot();

  return () => {
    alive = false;
    for (const dispose of disposers.splice(0)) dispose();
  };
}

const AVATARS = {
  "architect": "architect-avatar-v3.png",
  "brand-intelligence": "brand-strategist-avatar-v3.png",
  "copy-coach": "copy-writer-avatar-v3.png",
  "content-manager": "content-manager-avatar-v3.png",
  "funnel-builder": "funnel-builder-avatar-v3.png",
  "blaze": "blaze-avatar.png",
};

export function apply(ctx) {
  const React = ctx.react;
  loadFonts();
  ctx.pages.register({
    id: "main",
    title: "BraveBrand Team",
    layout: "workspace",
    placement: "topbar",
    primary: true,
    icon: ICON,
    component: function Team() {
      const ref = React.useRef(null);
      React.useEffect(() => {
        const node = ref.current;
        const root = node.shadowRoot || node.attachShadow({ mode: "open" });
        root.innerHTML = `<style>${CSS}</style>${MARKUP}`;
        return mountSheet(root, { agents: ctx.agents, host: ctx.host });
      }, []);
      return React.createElement("div", { ref, style: { height: "100%", minHeight: 0, flex: 1 } });
    },
  });
}
